export const getExplainUrl = (userId: string,
    params: ExplainParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/users/${userId}/effective-access/explain?${stringifiedParams}` : `/v1/users/${userId}/effective-access/explain`
}

export const explain = async (userId: string,
    params: ExplainParams, options?: Parameters<typeof apiFetch>[1]): Promise<Explanation> => {

  return apiFetch<Explanation>(getExplainUrl(userId,params),
  {
    ...options,
    method: 'GET'


  }
);}



export const getEnableUrl = (userId: string,) => {




  return `/v1/users/${userId}/enable`
}

export const enable = async (userId: string,
    changeUserStatus: ChangeUserStatus, options?: Parameters<typeof apiFetch>[1]): Promise<UserView> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<UserView>(getEnableUrl(userId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(changeUserStatus)
  }
);}
